function characterReplacement(s, k) {
  let maxLen = 0;
  const n = s.length;

  for (let i = 0; i < n; i++) {
    const counts = {};
    let maxFreq = 0;

    for (let j = i; j < n; j++) {
      const ch = s[j];
      counts[ch] = (counts[ch] || 0) + 1;
      if (counts[ch] > maxFreq) {
        maxFreq = counts[ch];
      }

      const windowLen = j - i + 1;
      if (windowLen - maxFreq <= k) {
        if (windowLen > maxLen) {
          maxLen = windowLen;
        }
      }
    }
  }

  return maxLen;
}

function characterReplacement(s, k) {
  const counts = {};
  let left = 0;
  let maxLen = 0;

  for (let right = 0; right < s.length; right++) {
    const ch = s[right];
    counts[ch] = (counts[ch] || 0) + 1;

    let maxFreq = 0;
    for (const key in counts) {
      if (counts[key] > maxFreq) {
        maxFreq = counts[key];
      }
    }

    while ((right - left + 1) - maxFreq > k) {
      counts[s[left]]--;
      left++;
      maxFreq = 0;
      for (const key in counts) {
        if (counts[key] > maxFreq) {
          maxFreq = counts[key];
        }
      }
    }

    const windowLen = right - left + 1;
    if (windowLen > maxLen) {
      maxLen = windowLen;
    }
  }

  return maxLen;
}
